        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

        * { margin: 0; padding: 0; box-sizing: border-box; }

        & {
            --purple: #3d1a6e;
            --purple-light: #6b3fa0;
            --pink: #ff4466;
            --yellow: #ffdd44;
            --cyan: #44ccff;
            --green: #44ff88;
            --bg: #0a0a1a;
            --bg-card: #12121f;
            --text: #e8e8f0;
            --text-dim: #6a6a8a;
            --border: rgba(255, 255, 255, 0.08);
            --glow: rgba(100, 50, 200, 0.15);
        }

        & {
            font-family: 'Inter', sans-serif;
            background: var(--bg);
            color: var(--text);
            overflow-x: hidden;
        }

        a { color: inherit; text-decoration: none; }

        /* Ambient */
        .ambient-glow {
            position: fixed;
            top: -200px;
            left: 50%;
            transform: translateX(-50%);
            width: 800px;
            height: 600px;
            background: radial-gradient(ellipse, var(--glow) 0%, transparent 70%);
            pointer-events: none;
            z-index: 0;
        }

        .content { position: relative; z-index: 10; }

        /* Floating blocks */
        .floating-blocks {
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            pointer-events: none;
            z-index: 1;
            overflow: hidden;
        }

        .float-block {
            position: absolute;
            border-radius: 6px;
            opacity: 0.12;
            animation: float-up linear infinite;
        }

        @keyframes float-up {
            0% { transform: translateY(110vh) rotate(0deg); }
            100% { transform: translateY(-10vh) rotate(360deg); }
        }

        /* Nav */
        .back-nav {
            position: fixed;
            top: 0; left: 0; right: 0;
            z-index: 100;
            padding: 1.2rem 2rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
            background: rgba(10, 10, 26, 0.85);
            backdrop-filter: blur(20px);
            border-bottom: 1px solid var(--border);
        }

        .back-link {
            font-size: 0.85rem;
            color: var(--text-dim);
            transition: color 0.2s;
        }

        .back-link:hover { color: var(--text); }

        .nav-title {
            font-size: 0.9rem;
            font-weight: 800;
            letter-spacing: 0.02em;
        }

        .nav-links-right {
            display: flex;
            gap: 1.5rem;
        }

        .nav-links-right a {
            font-size: 0.85rem;
            color: var(--text-dim);
            transition: color 0.2s;
            font-weight: 500;
        }

        .nav-links-right a:hover { color: var(--text); }

        /* Hero */
        .hero {
            min-height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-align: center;
            padding: 6rem 2rem 4rem;
        }

        .hero-title {
            font-size: clamp(3.5rem, 10vw, 7rem);
            font-weight: 900;
            letter-spacing: -0.03em;
            line-height: 1.0;
        }

        .hero-title .block { color: var(--pink); text-shadow: 0 0 40px rgba(255, 68, 102, 0.4); }
        .hero-title .drop { color: var(--yellow); text-shadow: 0 0 40px rgba(255, 221, 68, 0.4); }
        .hero-title .dg { color: var(--cyan); text-shadow: 0 0 40px rgba(68, 204, 255, 0.4); }

        .hero-tagline {
            font-size: clamp(1rem, 2.5vw, 1.3rem);
            color: var(--text-dim);
            margin-top: 2rem;
            max-width: 500px;
            line-height: 1.6;
        }

        .cta-buttons {
            margin-top: 2.5rem;
            display: flex;
            gap: 1rem;
            flex-wrap: wrap;
            justify-content: center;
        }

        .btn {
            display: inline-block;
            padding: 1rem 2.5rem;
            border-radius: 14px;
            font-family: 'Inter', sans-serif;
            font-size: 1rem;
            font-weight: 600;
            transition: all 0.3s;
        }

        .btn-primary {
            background: linear-gradient(135deg, var(--pink), #cc2255);
            color: white;
            border: none;
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 30px rgba(255, 68, 102, 0.4);
        }

        .btn-secondary {
            background: rgba(255, 255, 255, 0.06);
            color: var(--text);
            border: 1px solid var(--border);
        }

        .btn-secondary:hover {
            background: rgba(255, 255, 255, 0.1);
            transform: translateY(-2px);
        }

        /* Sections */
        section {
            padding: 6rem 2rem;
            max-width: 1000px;
            margin: 0 auto;
        }

        .section-label {
            font-size: 0.8rem;
            text-transform: uppercase;
            letter-spacing: 0.15em;
            color: var(--cyan);
            font-weight: 600;
            text-align: center;
            margin-bottom: 0.8rem;
        }

        .section-title {
            font-size: clamp(2rem, 4vw, 2.5rem);
            font-weight: 800;
            text-align: center;
            margin-bottom: 3rem;
            letter-spacing: -0.02em;
        }

        .divider {
            max-width: 1000px;
            margin: 0 auto;
            height: 1px;
            background: var(--border);
        }

        /* Features */
        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 1.5rem;
        }

        .feature-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 16px;
            padding: 2rem;
            transition: all 0.3s;
        }

        .feature-card:hover {
            transform: translateY(-4px);
            border-color: rgba(255, 255, 255, 0.15);
            box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);
        }

        .feature-icon { font-size: 2rem; margin-bottom: 1rem; }
        .feature-name { font-size: 1.1rem; font-weight: 700; margin-bottom: 0.5rem; }
        .feature-desc { font-size: 0.9rem; color: var(--text-dim); line-height: 1.6; }

        /* Privacy */
        .privacy-content { line-height: 1.8; color: var(--text-dim); font-size: 0.9rem; }
        .privacy-content h3 { color: var(--text); font-size: 1.1rem; margin: 2rem 0 0.5rem; }
        .privacy-content p { margin-bottom: 1rem; }
        .privacy-content a { color: var(--cyan); }

        /* Footer */
        footer {
            text-align: center;
            padding: 4rem 2rem;
            color: var(--text-dim);
            font-size: 0.85rem;
        }

        .footer-links {
            display: flex;
            gap: 2rem;
            justify-content: center;
            margin-bottom: 1rem;
            flex-wrap: wrap;
        }

        .footer-links a { color: var(--text-dim); transition: color 0.2s; }
        .footer-links a:hover { color: var(--text); }

        @media (max-width: 600px) {
            .back-nav { padding: 1rem 1.2rem; }
            section { padding: 4rem 1.5rem; }
            .nav-links-right { gap: 1rem; }
            .nav-links-right a { font-size: 0.75rem; }
        }

