        * { margin: 0; padding: 0; box-sizing: border-box; }

        & {
            --green: #00ff00;
            --green-dim: #00cc00;
            --green-dark: #004400;
            --bg: #020804;
            --bg-light: #0a1a0a;
            --text-dim: rgba(0, 255, 0, 0.5);
        }

        & {
            font-family: 'JetBrains Mono', monospace;
            background: var(--bg);
            color: var(--green);
            overflow-x: hidden;
        }

        a { color: inherit; }

        /* Matrix Rain Canvas */
        #matrix {
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            z-index: 0;
            opacity: 0.15;
        }

        /* Scanlines */
        &::after {
            content: '';
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            background: repeating-linear-gradient(
                transparent, transparent 2px,
                rgba(0, 0, 0, 0.1) 2px, rgba(0, 0, 0, 0.1) 4px
            );
            pointer-events: none;
            z-index: 1000;
        }

        .content {
            position: relative;
            z-index: 10;
        }

        /* Back nav */
        .back-nav {
            position: fixed;
            top: 0; left: 0; right: 0;
            z-index: 100;
            padding: 1rem 2rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
            background: rgba(2, 8, 4, 0.85);
            backdrop-filter: blur(12px);
            border-bottom: 1px solid rgba(0, 255, 0, 0.1);
        }

        .back-link {
            font-size: 0.85rem;
            color: var(--text-dim);
            text-decoration: none;
            transition: color 0.2s;
        }

        .back-link:hover { color: var(--green); }

        .nav-title {
            font-size: 0.85rem;
            font-weight: 700;
            letter-spacing: 0.1em;
        }

        .nav-links-right {
            display: flex;
            gap: 1.5rem;
        }

        .nav-links-right a {
            font-size: 0.8rem;
            color: var(--text-dim);
            text-decoration: none;
            transition: color 0.2s;
        }

        .nav-links-right a:hover { color: var(--green); }

