        .feature-card:hover {
            border-color: rgba(0, 255, 0, 0.4);
            background: rgba(0, 255, 0, 0.05);
            box-shadow: 0 0 20px rgba(0, 255, 0, 0.1);
        }

        .feature-icon { font-size: 2rem; margin-bottom: 1rem; }
