        .screenshots-scroll {
            display: flex;
            gap: 1.5rem;
            overflow-x: auto;
            padding: 1rem 0 2rem;
            scroll-snap-type: x mandatory;
            -webkit-overflow-scrolling: touch;
        }

        .screenshots-scroll::-webkit-scrollbar { height: 4px; }
        .screenshots-scroll::-webkit-scrollbar-track { background: rgba(0, 255, 0, 0.05); }
        .screenshots-scroll::-webkit-scrollbar-thumb { background: rgba(0, 255, 0, 0.3); }

        .screenshot-item {
            flex: 0 0 auto;
            width: 220px;
            scroll-snap-align: start;
        }

        .screenshot-item img {
            width: 100%;
            border: 1px solid rgba(0, 255, 0, 0.2);
            display: block;
        }

        .screenshot-placeholder {
            width: 100%;
            aspect-ratio: 9/16;
            border: 1px dashed rgba(0, 255, 0, 0.2);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--text-dim);
            font-size: 0.8rem;
            background: rgba(0, 255, 0, 0.02);
        }

        /* Tiers */
        .tiers-list { display: flex; flex-direction: column; gap: 0.5rem; }

        .tier-row {
            display: flex;
            align-items: center;
            padding: 0.8rem 1.5rem;
            border: 1px solid rgba(0, 255, 0, 0.1);
            background: rgba(0, 255, 0, 0.02);
            gap: 1rem;
            transition: all 0.3s;
        }

        .tier-row:hover {
            border-color: var(--tier-color, var(--green));
            background: rgba(0, 255, 0, 0.05);
        }

        .tier-num { font-weight: 700; font-size: 0.85rem; color: var(--tier-color, var(--green)); min-width: 30px; }
        .tier-name { flex: 1; font-size: 0.9rem; color: var(--tier-color, var(--green)); }
        .tier-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--tier-color, var(--green)); box-shadow: 0 0 8px var(--tier-color, var(--green)); }

        /* Privacy */
        .privacy-content { line-height: 1.8; color: var(--text-dim); font-size: 0.85rem; }
        .privacy-content h3 { color: var(--green); font-size: 1rem; margin: 2rem 0 0.5rem; letter-spacing: 0.05em; }
        .privacy-content p { margin-bottom: 1rem; }
        .privacy-content a { color: var(--green-dim); }

        /* Footer */
        footer {
            text-align: center;
            padding: 4rem 2rem;
            color: var(--text-dim);
            font-size: 0.8rem;
        }

        .footer-links {
            display: flex;
            gap: 2rem;
            justify-content: center;
            margin-bottom: 1rem;
            flex-wrap: wrap;
        }

        .footer-links a { color: var(--green-dim); text-decoration: none; }
        .footer-links a:hover { color: var(--green); }

        /* Animations */
        @keyframes flicker {
            0%, 100% { opacity: 1; }
            92% { opacity: 1; }
            93% { opacity: 0.8; }
            94% { opacity: 1; }
            96% { opacity: 0.9; }
            97% { opacity: 1; }
        }

        @keyframes blink {
            0%, 100% { opacity: 1; }
            50% { opacity: 0; }
        }

        @media (max-width: 600px) {
            section { padding: 4rem 1.5rem; }
            .feature-card { padding: 1.5rem; }
            .screenshot-item { width: 180px; }
            .back-nav { padding: 0.8rem 1rem; }
        }

hacker-life.css:
        @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;700&display=swap');

        * { margin: 0; padding: 0; box-sizing: border-box; }

        & {
            --green: #33ff88;
            --green-dim: #1a9955;
            --cyan: #00e5ff;
            --red: #ff4444;
            --amber: #ffaa22;
            --bg: #030a06;
            --bg-light: #081a10;
            --text-dim: rgba(51, 255, 136, 0.5);
        }

        & {
            font-family: 'JetBrains Mono', monospace;
            background: var(--bg);
            color: var(--green);
            overflow-x: hidden;
        }

        a { color: inherit; }

        /* Scanlines */
        &::after {
            content: '';
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            background: repeating-linear-gradient(
                transparent, transparent 2px,
                rgba(0, 0, 0, 0.08) 2px, rgba(0, 0, 0, 0.08) 4px
            );
            pointer-events: none;
            z-index: 1000;
        }

        .content {
            position: relative;
            z-index: 10;
        }

        /* Nav */
        .back-nav {
            position: fixed;
            top: 0; left: 0; right: 0;
            z-index: 100;
            padding: 1rem 2rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
            background: rgba(3, 10, 6, 0.85);
            backdrop-filter: blur(12px);
            border-bottom: 1px solid rgba(51, 255, 136, 0.1);
        }

        .back-link {
            font-size: 0.85rem;
            color: var(--text-dim);
            text-decoration: none;
            transition: color 0.2s;
        }

        .back-link:hover { color: var(--green); }

        .nav-title {
            font-size: 0.85rem;
            font-weight: 700;
            letter-spacing: 0.1em;
        }

        .nav-links-right {
            display: flex;
            gap: 1.5rem;
        }

        .nav-links-right a {
            font-size: 0.8rem;
            color: var(--text-dim);
            text-decoration: none;
            transition: color 0.2s;
        }

        .nav-links-right a:hover { color: var(--green); }

        /* Hero */
        .hero {
            min-height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-align: center;
            padding: 6rem 2rem 4rem;
            position: relative;
        }

        .hero-badge {
            font-size: 0.75rem;
            letter-spacing: 0.2em;
            color: var(--amber);
            border: 1px solid rgba(255, 170, 34, 0.3);
            padding: 0.4rem 1.2rem;
            margin-bottom: 2rem;
            text-transform: uppercase;
        }

        .hero-title {
            font-size: clamp(3rem, 10vw, 6rem);
            font-weight: 700;
            letter-spacing: 0.05em;
            text-shadow: 0 0 40px rgba(51, 255, 136, 0.4), 0 0 80px rgba(51, 255, 136, 0.15);
            animation: flicker 5s infinite;
        }

        .hero-sub {
            font-size: clamp(1rem, 2.5vw, 1.6rem);
            color: var(--text-dim);
            margin-top: 0.5rem;
            letter-spacing: 0.25em;
        }

        .hero-tagline {
            font-size: clamp(0.85rem, 1.8vw, 1rem);
            color: var(--text-dim);
            margin-top: 2rem;
            max-width: 550px;
            line-height: 1.7;
        }

        .hero-terminal {
            margin-top: 3rem;
            background: rgba(51, 255, 136, 0.03);
            border: 1px solid rgba(51, 255, 136, 0.15);
            padding: 1.5rem 2rem;
            text-align: left;
            max-width: 500px;
            width: 100%;
            font-size: 0.85rem;
            line-height: 1.8;
        }

        .terminal-line { color: var(--text-dim); }
        .terminal-line .cmd { color: var(--green); }
        .terminal-line .warn { color: var(--amber); }
        .terminal-line .err { color: var(--red); }
        .cursor-blink { animation: blink 1s step-end infinite; }

        .cta-buttons {
            margin-top: 2.5rem;
            display: flex;
            gap: 1rem;
            flex-wrap: wrap;
            justify-content: center;
        }

        .btn {
            display: inline-block;
            padding: 1rem 2.5rem;
            border: 2px solid var(--green);
            color: var(--green);
            text-decoration: none;
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.95rem;
            font-weight: 500;
            letter-spacing: 0.05em;
            background: rgba(51, 255, 136, 0.05);
            transition: all 0.3s;
        }

        .btn:hover {
            background: rgba(51, 255, 136, 0.12);
            box-shadow: 0 0 30px rgba(51, 255, 136, 0.2);
            transform: translateY(-2px);
        }

        .btn-primary {
            background: var(--green);
            color: var(--bg);
            font-weight: 700;
        }

        .btn-primary:hover {
            background: #55ffaa;
            box-shadow: 0 0 40px rgba(51, 255, 136, 0.4);
        }

        .coming-soon-badge {
            background: linear-gradient(135deg, rgba(51, 255, 136, 0.1), rgba(0, 200, 100, 0.05));
            border: 2px solid rgba(51, 255, 136, 0.3);
            border-radius: 16px;
            padding: 2rem 3rem;
            text-align: center;
            box-shadow: 0 0 40px rgba(51, 255, 136, 0.1), inset 0 0 60px rgba(51, 255, 136, 0.03);
            animation: pulse-glow 3s ease-in-out infinite;
        }

        @keyframes pulse-glow {
            0%, 100% { box-shadow: 0 0 40px rgba(51, 255, 136, 0.1), inset 0 0 60px rgba(51, 255, 136, 0.03); }
            50% { box-shadow: 0 0 60px rgba(51, 255, 136, 0.2), inset 0 0 80px rgba(51, 255, 136, 0.05); }
        }

        .coming-soon-icon {
            font-size: 2.5rem;
            margin-bottom: 0.5rem;
        }

        .coming-soon-text {
            font-size: 1.5rem;
            font-weight: 700;
            letter-spacing: 0.2em;
            color: var(--green);
            text-shadow: 0 0 20px rgba(51, 255, 136, 0.5);
            margin-bottom: 1rem;
        }

        .coming-soon-platforms {
            font-size: 1rem;
            color: var(--text-dim);
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 0.5rem;
        }

        .platform-logo {
            width: 18px;
            height: 18px;
            opacity: 0.8;
        }

        .platform-divider {
            color: rgba(51, 255, 136, 0.3);
            margin: 0 0.8rem;
        }

        /* Sections */
        section {
            padding: 6rem 2rem;
            max-width: 1000px;
            margin: 0 auto;
        }

        .section-title {
            font-size: 1.5rem;
            letter-spacing: 0.15em;
            margin-bottom: 3rem;
            text-align: center;
            text-shadow: 0 0 20px rgba(51, 255, 136, 0.3);
        }

        .section-title::before { content: '> '; color: var(--text-dim); }

        .divider {
            max-width: 1000px;
            margin: 0 auto;
            height: 1px;
            background: linear-gradient(90deg, transparent, rgba(51, 255, 136, 0.25), transparent);
        }

        /* Features */
        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 2rem;
        }

        .feature-card {
            border: 1px solid rgba(51, 255, 136, 0.12);
            padding: 2rem;
            background: rgba(51, 255, 136, 0.02);
            transition: all 0.3s;
        }

        .feature-card:hover {
            border-color: rgba(51, 255, 136, 0.35);
            background: rgba(51, 255, 136, 0.05);
            box-shadow: 0 0 20px rgba(51, 255, 136, 0.08);
        }

        .feature-icon { font-size: 2rem; margin-bottom: 1rem; }
        .feature-name { font-size: 1rem; font-weight: 700; margin-bottom: 0.5rem; letter-spacing: 0.05em; }
        .feature-desc { font-size: 0.85rem; color: var(--text-dim); line-height: 1.6; }

        /* Mini-games */
        .minigames-list {
            display: flex;
