        .minigame-row {
            display: flex;
            align-items: center;
            gap: 1.2rem;
            padding: 1.2rem 1.5rem;
            border: 1px solid rgba(51, 255, 136, 0.1);
            background: rgba(51, 255, 136, 0.02);
            transition: all 0.3s;
        }

        .minigame-row:hover {
            border-color: rgba(51, 255, 136, 0.3);
            background: rgba(51, 255, 136, 0.05);
        }

        .minigame-icon { font-size: 1.8rem; min-width: 40px; text-align: center; }
        .minigame-name { font-weight: 700; font-size: 0.9rem; letter-spacing: 0.05em; }
        .minigame-desc { font-size: 0.8rem; color: var(--text-dim); margin-top: 0.3rem; }

        /* Ranks */
        .ranks-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
            gap: 0.8rem;
        }

        .rank-card {
            text-align: center;
            padding: 1.2rem;
            border: 1px solid rgba(51, 255, 136, 0.1);
            background: rgba(51, 255, 136, 0.02);
            transition: all 0.3s;
        }

        .rank-card:hover {
            border-color: var(--rank-color, var(--green));
            box-shadow: 0 0 15px color-mix(in srgb, var(--rank-color, var(--green)) 30%, transparent);
        }

        .rank-level { font-size: 0.7rem; color: var(--text-dim); letter-spacing: 0.15em; margin-bottom: 0.3rem; }
        .rank-name { font-size: 0.85rem; font-weight: 700; color: var(--rank-color, var(--green)); }

        /* Screenshots */
        .screenshots-scroll {
            display: flex;
            gap: 1.5rem;
            overflow-x: auto;
            padding: 1rem 0 2rem;
            scroll-snap-type: x mandatory;
            -webkit-overflow-scrolling: touch;
        }

        .screenshots-scroll::-webkit-scrollbar { height: 4px; }
        .screenshots-scroll::-webkit-scrollbar-track { background: rgba(51, 255, 136, 0.05); }
        .screenshots-scroll::-webkit-scrollbar-thumb { background: rgba(51, 255, 136, 0.3); }

        .screenshot-item {
            flex: 0 0 auto;
            scroll-snap-align: start;
        }

        .screenshot-placeholder {
            width: 300px;
            aspect-ratio: 16/9;
            border: 1px dashed rgba(51, 255, 136, 0.2);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--text-dim);
            font-size: 0.8rem;
            background: rgba(51, 255, 136, 0.02);
        }

        /* Privacy */
        .privacy-content { line-height: 1.8; color: var(--text-dim); font-size: 0.85rem; }
        .privacy-content h3 { color: var(--green); font-size: 1rem; margin: 2rem 0 0.5rem; letter-spacing: 0.05em; }
        .privacy-content p { margin-bottom: 1rem; }
        .privacy-content a { color: var(--green-dim); }

        /* Footer */
        footer {
            text-align: center;
            padding: 4rem 2rem;
            color: var(--text-dim);
            font-size: 0.8rem;
        }

        .footer-links {
            display: flex;
            gap: 2rem;
            justify-content: center;
            margin-bottom: 1rem;
            flex-wrap: wrap;
        }

        .footer-links a { color: var(--green-dim); text-decoration: none; }
        .footer-links a:hover { color: var(--green); }

        @keyframes flicker {
            0%, 100% { opacity: 1; }
            90% { opacity: 1; }
            91% { opacity: 0.85; }
            92% { opacity: 1; }
            95% { opacity: 0.9; }
            96% { opacity: 1; }
        }

        @keyframes blink {
            0%, 100% { opacity: 1; }
            50% { opacity: 0; }
        }

        /* Floating particles */
        .particles {
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            z-index: 0;
            pointer-events: none;
        }

        @media (max-width: 600px) {
            section { padding: 4rem 1.5rem; }
            .feature-card { padding: 1.5rem; }
            .back-nav { padding: 0.8rem 1rem; }
            .hero-terminal { padding: 1rem; font-size: 0.75rem; }
        }

beamer-connect.css:
&{
  --bg:#0a0a0c;
  --bg-2:#121117;
  --bg-3:#16151c;
  --watch:#b22222;
  --watch-deep:#7d1414;
  --gold:#c9a24b;
  --text:#e8e6e1;
  --muted:#9a978f;
  --line:rgba(255,255,255,.08);
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
&{
  background:var(--bg);
  color:var(--text);
  font-family:'Inter',system-ui,sans-serif;
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
a{color:inherit;text-decoration:none}
img{display:block;max-width:100%}

.wrap{max-width:1180px;margin:0 auto;padding:0 24px}

/* ---------- NAV ---------- */
nav{
  position:fixed;top:0;left:0;right:0;z-index:50;
  display:flex;align-items:center;justify-content:space-between;
  padding:16px 24px;
  background:linear-gradient(180deg,rgba(10,10,12,.95),rgba(10,10,12,0));
  backdrop-filter:blur(8px);
}
.logo{
  font-family:'Oswald',sans-serif;font-weight:700;
  font-size:20px;letter-spacing:3px;text-transform:uppercase;
}
.logo .glow{color:var(--gold)}
.nav-links{display:flex;gap:28px;font-size:13px;letter-spacing:1px;text-transform:uppercase;font-weight:500}
.nav-links a{color:var(--muted);transition:color .2s}
.nav-links a:hover{color:var(--text)}
@media(max-width:640px){.nav-links{display:none}}

/* ---------- HERO ---------- */
.hero-hub{
  position:relative;min-height:88vh;
  display:flex;align-items:center;
  padding:130px 0 90px;overflow:hidden;
}
.hero-hub-bg{
  position:absolute;inset:0;
  background:
    radial-gradient(ellipse at 20% 20%,rgba(201,162,75,.15),transparent 55%),
    radial-gradient(ellipse at 85% 78%,rgba(70,110,180,.12),transparent 58%),
    linear-gradient(180deg,var(--bg-2) 0%,var(--bg) 100%);
}
.hero-hub-bg::after{
  content:"";position:absolute;inset:0;
  background:linear-gradient(180deg,transparent 62%,var(--bg) 100%);
}
.hero-hub-content{position:relative;z-index:2;width:100%}
.eyebrow{
  font-family:'Special Elite',monospace;
  font-size:12px;letter-spacing:4px;text-transform:uppercase;
  color:var(--gold);margin-bottom:18px;
  display:flex;align-items:center;gap:12px;
}
.eyebrow::before{content:"";width:36px;height:1px;background:var(--gold)}
.hero-hub h1{
  font-family:'Oswald',sans-serif;font-weight:700;
  font-size:clamp(46px,9vw,104px);line-height:.92;
  letter-spacing:1px;text-transform:uppercase;
  max-width:16ch;margin-bottom:20px;text-shadow:0 4px 40px rgba(0,0,0,.6);
}
.hero-hub p.lede{
  font-size:clamp(16px,2.1vw,20px);color:#d8d5cd;
  max-width:52ch;margin-bottom:14px;line-height:1.5;
}
.hero-hub p.sub{color:var(--muted);max-width:52ch;margin-bottom:30px;font-size:15.5px}
.cta-row{display:flex;gap:14px;flex-wrap:wrap;align-items:center}
.btn{
  font-family:'Oswald',sans-serif;font-weight:600;
  font-size:14px;letter-spacing:2px;text-transform:uppercase;
  padding:15px 30px;border:none;cursor:pointer;transition:all .2s;
  display:inline-flex;align-items:center;gap:9px;
}
.btn-primary{background:var(--watch);color:#fff}
.btn-primary:hover{background:var(--watch-deep);transform:translateY(-2px)}
.btn-ghost{background:transparent;color:var(--text);border:1px solid var(--line)}
.btn-ghost:hover{border-color:var(--gold);color:var(--gold)}
.status-pill{
  font-family:'Special Elite',monospace;font-size:11px;letter-spacing:2px;
  text-transform:uppercase;color:var(--muted);
  display:inline-flex;align-items:center;gap:8px;margin-top:26px;
}
.status-pill .dot{width:7px;height:7px;border-radius:50%;background:var(--gold);box-shadow:0 0 10px var(--gold)}

/* ---------- SECTION SHELL ---------- */
section{padding:96px 0}
.sec-head{margin-bottom:48px}
.sec-eyebrow{
  font-family:'Special Elite',monospace;font-size:12px;letter-spacing:4px;
  text-transform:uppercase;color:var(--gold);margin-bottom:12px;
}
.sec-title{
  font-family:'Oswald',sans-serif;font-weight:700;
  font-size:clamp(30px,5vw,52px);line-height:1;letter-spacing:1px;
  text-transform:uppercase;
}
.sec-sub{color:var(--muted);max-width:56ch;margin-top:16px;font-size:16px}

/* ---------- FEATURES ---------- */
.features{background:var(--bg-2);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.features-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}
@media(max-width:680px){.features-grid{grid-template-columns:1fr}}
.feature{
  border:1px solid var(--line);background:var(--bg-3);padding:32px 30px;
  transition:transform .25s,border-color .25s;
}
.feature:hover{transform:translateY(-4px);border-color:var(--gold)}
.feature-tag{
  font-family:'Special Elite',monospace;font-size:11px;letter-spacing:3px;
  text-transform:uppercase;color:var(--gold);margin-bottom:10px;
}
.feature h3{font-family:'Oswald',sans-serif;font-weight:600;font-size:24px;letter-spacing:1px;text-transform:uppercase;margin-bottom:10px}
.feature p{color:var(--muted);font-size:14.5px}

/* ---------- REQUIREMENTS ---------- */
.reqs-inner{max-width:760px}
.reqs-list{list-style:none;margin-top:26px;display:grid;gap:14px}
.reqs-list li{
  display:flex;gap:14px;align-items:flex-start;
  color:var(--muted);font-size:15px;
  padding-bottom:14px;border-bottom:1px solid var(--line);
}
.reqs-list li:last-child{border-bottom:none}
.reqs-list .k{
  font-family:'Oswald',sans-serif;font-weight:600;letter-spacing:1px;
  text-transform:uppercase;color:var(--text);min-width:150px;font-size:14px;
}

/* ---------- FOOTER ---------- */
footer{padding:56px 0 40px;border-top:1px solid var(--line)}
.foot-grid{display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:28px}
.foot-links{display:flex;gap:24px;flex-wrap:wrap;font-size:13px;letter-spacing:1px;text-transform:uppercase;color:var(--muted)}
.foot-links a:hover{color:var(--text)}
.copyright{color:var(--muted);font-size:12px;letter-spacing:1px;margin-top:32px}

@media(prefers-reduced-motion:reduce){
  *{animation:none!important;transition:none!important;scroll-behavior:auto!important}
}
